//! Journal routes — the project's lab log: plain markdown files at
//! <project>/.journal/logs/YYYY-MM-DD.md (one per day), written directly by any
//! agent or generated by the journal writer. Read-only for the display layer;
//! POST /journals/generate kicks the writer on demand. Journals never enter
//! mem0 — no vector search, no mirror, no fact count.

import path from 'node:path';

import type { Static } from '@sinclair/typebox';
import type { FastifyInstance } from 'fastify';

import {
  JournalsPendingResponse,
  JournalsResponse,
  JournalProjectBody,
  JournalScopeBody,
  JournalScopeQuery,
  OkResponse,
  ProjectIdParams,
} from '../schemas';
import { listJournalFiles as scanJournalFiles } from '../journal-fs';
import { generateMissingJournals, planMissingJournals, regenerateJournals } from '../core/journal-gen';
import { projectRows } from '../store';

export default async function journalRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: Static<typeof ProjectIdParams> }>(
    '/projects/:projectId/journals',
    {
      schema: { params: ProjectIdParams, response: { 200: JournalsResponse }, operationId: 'listJournals' },
    },
    async (req) => ({ journals: listJournalFiles(app.cfg.dataDir, req.params.projectId) }),
  );

  // Pre-check for the UI's generate button: days with memory activity but no
  // journal file for one project (?projectId=) or all — no LLM involved.
  app.get<{ Querystring: Static<typeof JournalScopeQuery> }>(
    '/journals/pending',
    {
      schema: { querystring: JournalScopeQuery, response: { 200: JournalsPendingResponse }, operationId: 'getJournalPending' },
    },
    async (req) => ({
      pending: await planMissingJournals(app.cfg.llm, app.cfg.dataDir, req.query.projectId?.trim() || undefined),
    }),
  );

  // Manual trigger: kick the writer without waiting for the next hourly tick.
  // Fire-and-forget — a multi-day backfill is LLM-bound. Body scopes to one
  // project (the UI button); absent → all projects.
  app.post<{ Body: Static<typeof JournalScopeBody> }>(
    '/journals/generate',
    {
      schema: { body: JournalScopeBody, response: { 200: OkResponse }, operationId: 'generateJournals' },
    },
    async (req) => {
      void generateMissingJournals(app.cfg.llm, app.cfg.dataDir, req.body.projectId?.trim() || undefined);
      return { ok: true };
    },
  );

  // Debug trigger: delete the project's past-date journals and regenerate them
  // from the same memories. Deletion is synchronous (the list visibly empties,
  // then refills as files land); generation is fire-and-forget like above.
  // projectIds required — silently wiping every project is not acceptable.
  app.post<{ Body: Static<typeof JournalProjectBody> }>(
    '/journals/regenerate',
    {
      schema: { body: JournalProjectBody, response: { 200: OkResponse }, operationId: 'regenerateJournals' },
    },
    async (req) => {
      void regenerateJournals(app.cfg.llm, app.cfg.dataDir, req.body.projectId.trim());
      return { ok: true };
    },
  );
}

/** Scan <project>/.journal/logs/*.md for one registered project. Unregistered or
 *  virtual (non-absolute) project ids → empty list; a missing directory
 *  (remote mode can't see project filesystems) is equally empty. */
function listJournalFiles(dataDir: string, projectId: string) {
  const registered = projectRows(dataDir).some((r) => r.id === projectId);
  if (!registered || !path.isAbsolute(projectId)) return [];
  return scanJournalFiles(projectId);
}
